import { render } from '@solidjs/web';
import {
  createSignal,
  createStore,
  createOptimisticStore,
  action,
  refresh,
  For,
  Loading,
} from 'solid-js';
import { api, newId } from './api';
import './styles.css';

function Todos() {
  const [error, setError] = createSignal('');
  const [todos, setTodos] = createStore([
    { id: 1, text: 'Learn actions', done: true },
    { id: 2, text: 'Learn optimistic stores', done: false },
  ]);

  const toggle = action(function* (id) {
    setTodos((draft) => {
      const todo = draft.find((todo) => todo.id === id);
      todo.done = !todo.done;
    });
    yield api.toggle(id);
  });

  const add = action(function* (text) {
    const todo = { id: newId(), text, done: false };
    setTodos((draft) => {
      draft.push(todo);
    });
    yield api.add(todo);
  });

  return (
    <Loading fallback={<p>Loading todos...</p>}>
      <form
        onSubmit={(event) => {
          event.preventDefault();
          const input = event.currentTarget.elements.text;
          if (input.value.trim()) add(input.value);
          input.value = '';
        }}
      >
        <input name="text" placeholder="New todo" /> <button>Add</button>
      </form>
      <For each={todos}>
        {(todo) => (
          <label class={{ todo: true, pending: !!todo.pending }}>
            <input
              type="checkbox"
              checked={todo.done}
              onChange={() => toggle(todo.id).catch((err) => setError(err.message))}
            />{' '}
            {todo.text}
          </label>
        )}
      </For>
      <p>
        <label>
          <input
            type="checkbox"
            onChange={(event) => (api.failNext = event.currentTarget.checked)}
          />{' '}
          Fail the next toggle
        </label>
      </p>
      <p role="alert">{error()}</p>
    </Loading>
  );
}

render(() => <Todos />, document.getElementById('app'));

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// A pretend server holding the todo list. Saves take 800ms.
let serverTodos = [
  { id: 1, text: 'Learn actions', done: true },
  { id: 2, text: 'Learn optimistic stores', done: false },
];
let nextId = 3;
export const api = {
  failNext: false,
  async list() {
    await sleep(100);
    return structuredClone(serverTodos);
  },
  async toggle(id) {
    await sleep(800);
    if (api.failNext) {
      api.failNext = false;
      throw new Error('The server rejected that change.');
    }
    serverTodos = serverTodos.map((t) => (t.id === id ? { ...t, done: !t.done } : t));
  },
  async add(todo) {
    await sleep(800);
    serverTodos = [...serverTodos, todo];
  },
};

export const newId = () => nextId++;

.todo {
  display: block;
  margin: 0.25rem 0;
  font-family: sans-serif;
}

.todo.pending {
  opacity: 0.5;
}

import { render } from '@solidjs/web';
import {
  createSignal,
  createStore,
  createOptimisticStore,
  action,
  refresh,
  For,
  Loading,
} from 'solid-js';
import { api, newId } from './api';
import './styles.css';

function Todos() {
  const [error, setError] = createSignal('');
  const [todos, setTodos] = createOptimisticStore(() => api.list(), []);

  const toggle = action(function* (id) {
    setTodos((draft) => {
      const todo = draft.find((todo) => todo.id === id);
      todo.done = !todo.done;
      todo.pending = true;
    });
    yield api.toggle(id);
    refresh(todos);
  });

  const add = action(function* (text) {
    const todo = { id: newId(), text, done: false };
    setTodos((draft) => {
      draft.push({ ...todo, pending: true });
    });
    yield api.add(todo);
    refresh(todos);
  });

  return (
    <Loading fallback={<p>Loading todos...</p>}>
      <form
        onSubmit={(event) => {
          event.preventDefault();
          const input = event.currentTarget.elements.text;
          if (input.value.trim()) add(input.value);
          input.value = '';
        }}
      >
        <input name="text" placeholder="New todo" /> <button>Add</button>
      </form>
      <For each={todos}>
        {(todo) => (
          <label class={{ todo: true, pending: !!todo.pending }}>
            <input
              type="checkbox"
              checked={todo.done}
              onChange={() => toggle(todo.id).catch((err) => setError(err.message))}
            />{' '}
            {todo.text}
          </label>
        )}
      </For>
      <p>
        <label>
          <input
            type="checkbox"
            onChange={(event) => (api.failNext = event.currentTarget.checked)}
          />{' '}
          Fail the next toggle
        </label>
      </p>
      <p role="alert">{error()}</p>
    </Loading>
  );
}

render(() => <Todos />, document.getElementById('app'));

